import gurobipy as gp
from gurobipy import GRB
suppliers = ['S1', 'S2', 'S3', 'S4', 'S5', 'S6', 'S7', 'S8', 'S9', 'S10']
customers = ['C1', 'C2', 'C3', 'C4', 'C5', 'C6', 'C7', 'C8', 'C9', 'C10']
demand = {'C1': 216, 'C2': 168, 'C3': 264, 'C4': 216, 'C5': 216, 'C6': 192, 'C7': 144, 'C8': 168, 'C9': 168, 'C10': 168}
supply_capacity = {'S1': 288, 'S2': 288, 'S3': 264, 'S4': 264, 'S5': 216, 'S6': 216, 'S7': 168, 'S8': 216, 'S9': 240, 'S10': 168}
cost = {'S1': {'C1': 590.3648136504455, 'C2': 23.66917260732249, 'C3': 88.89005869765714, 'C4': 497.5222880707461, 'C5': 466.09034321595647, 'C6': 29.02209682706321, 'C7': 23.675244833973835, 'C8': 23.67776028811744, 'C9': 0.3118394914937161, 'C10': 58.895473920714416}, 'S2': {'C1': 2042.0715001593624, 'C2': 2133.978484314172, 'C3': 705.15912033561, 'C4': 101.59454516295598, 'C5': 2052.937657376311, 'C6': 1738.754951414345, 'C7': 101.61094965654742, 'C8': 101.61062174376056, 'C9': 122.45214268700826, 'C10': 67.29170751036096}, 'S3': {'C1': 22.297222160217984, 'C2': 497.9271939314995, 'C3': 1653.0828862073265, 'C4': 23.68545123339267, 'C5': 1386.0807887282344, 'C6': 26.13715280763276, 'C7': 497.6220482906461, 'C8': 498.0935847133144, 'C9': 865.3816296318804, 'C10': 1008.671739462098}, 'S4': {'C1': 960.7814533858372, 'C2': 49.128300053752405, 'C3': 1324.238697073691, 'C4': 1032.2095478151716, 'C5': 0.0780472539272086, 'C6': 53.308268726049285, 'C7': 49.1364167175093, 'C8': 1031.8214424894484, 'C9': 466.00495307991264, 'C10': 1351.8189071012546}, 'S5': {'C1': 1471.2721666392908, 'C2': 85.6956072820555, 'C3': 38.89266823851542, 'C4': 1542.0500358120464, 'C5': 112.20514372003504, 'C6': 82.3702016356405, 'C7': 1542.3399196620971, 'C8': 85.69238745806277, 'C9': 1924.9360769614243, 'C10': 1094.6695960752636}, 'S6': {'C1': 191.9058726130392, 'C2': 158.50401031820448, 'C3': 91.02045349777458, 'C4': 184.44747201726196, 'C5': 968.146798696633, 'C6': 284.1076062070199, 'C7': 8.791061587686942, 'C8': 158.70523835548545, 'C9': 27.943874345249665, 'C10': 929.807168280051}, 'S7': {'C1': 81.23891457326876, 'C2': 0.3744642223062507, 'C3': 2079.46686537067, 'C4': 0.3065671755503025, 'C5': 1031.7772962191823, 'C6': 7.203964492497209, 'C7': 0.0762307224176269, 'C8': 0.0324738795480065, 'C9': 23.68582796642136, 'C10': 849.9799406578097}, 'S8': {'C1': 56.09931096546136, 'C2': 935.6143108671334, 'C3': 73.08824617002863, 'C4': 52.00392409272077, 'C5': 4.025792388934198, 'C6': 1002.2327657984296, 'C7': 935.7766029588662, 'C8': 935.7007252277288, 'C9': 612.8698719325438, 'C10': 1348.8366145919845}, 'S9': {'C1': 4.502283326860296, 'C2': 0.3899585342810754, 'C3': 1782.4662178163346, 'C4': 0.0063459066127182, 'C5': 1031.9910114913148, 'C6': 129.50665619510303, 'C7': 0.2118319573481142, 'C8': 0.645730107353115, 'C9': 497.62723911435927, 'C10': 40.46575554562011}, 'S10': {'C1': 333.6869270439132, 'C2': 277.4719386113677, 'C3': 86.02096892455509, 'C4': 277.30836609256806, 'C5': 1004.4649084520336, 'C6': 19.9503368158576, 'C7': 13.202073690286834, 'C8': 238.14321521805863, 'C9': 411.0580332361589, 'C10': 941.7526365563969}}
for i in suppliers:
    if i not in cost:
        raise ValueError(f'Missing cost data for supplier {i}')
    for j in customers:
        if j not in cost[i]:
            raise ValueError(f'Missing cost data for supplier {i}, customer {j}')
for j in customers:
    if j not in demand:
        raise ValueError(f'Missing demand data for customer {j}')
for i in suppliers:
    if i not in supply_capacity:
        raise ValueError(f'Missing supply capacity data for supplier {i}')
m = gp.Model('Original_RAG_TP')
x = m.addVars(suppliers, customers, lb=0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum((cost[i][j] * x[i, j] for i in suppliers for j in customers)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x[i, j] for i in suppliers)) >= demand[j] for j in customers), name='')
m.addConstrs((gp.quicksum((x[i, j] for j in customers)) <= supply_capacity[i] for i in suppliers), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for variable in m.getVars():
        print(f'{variable.VarName}: {variable.X}')
else:
    print(f'Solver status: {m.Status}')